\title{The Constructive Core of the Probabilistic Method:\\
Ramsey Lower Bounds, the Lov\'asz Local Lemma, and Tur\'an's Theorem}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
The probabilistic method proves the existence of combinatorial objects by exhibiting a probability space in which a random object has the desired property with positive probability. We present a unified, self-contained development of three pillars of the method, emphasizing throughout that the underlying arguments are \emph{constructive} --- finite counting statements in disguise. First, we prove Erd\H{o}s's exponential lower bound on the diagonal Ramsey numbers, $R(k,k) > 2^{k/2}$, entirely by a finite union-bound count over edge-colorings, with no appeal to measure theory. Second, we develop the measure-theoretic backbone of the probabilistic method in a general probability space: the first-moment (union-bound) existence principle, the independent case of the Lov\'asz Local Lemma (yielding the exact product formula $\mu(\bigcap A_i^c) = \prod (1 - \mu(A_i))$), and a general \emph{chain-rule positivity principle} that isolates the essential inductive content of the Local Lemma under a single conditional-avoidability hypothesis. Third, we package Tur\'an's theorem in its classical real-analytic form, bounding the edges of a $K_{r+1}$-free graph by $(1 - 1/r)n^2/2$, with the bound achieved constructively by the Tur\'an graph. We conclude with the algorithmic reading of these results --- the Moser--Tardos resampling perspective --- and the sense in which Erd\H{o}s's existence proofs are algorithms in disguise.
\end{abstract}

\noindent\textbf{Keywords:} probabilistic method, Ramsey numbers, Lov\'asz Local Lemma, Tur\'an's theorem, first-moment method, union bound, extremal graph theory, constructive existence.

\section{Introduction}

Since Erd\H{o}s's 1947 note on the Ramsey numbers, the \emph{probabilistic method} has grown from a single ingenious trick into a systematic engine of existence proofs. Its logical shape is always the same: to prove that an object with a desired property $P$ exists, construct a probability space of candidate objects and show that a random candidate has property $P$ with positive probability. An event of positive probability is nonempty, so a candidate with property $P$ must exist.

This paper assembles a coherent treatment of three landmark applications and the abstract principles beneath them, with two guiding themes. \emph{Unification}: the Ramsey lower bound, the Lov\'asz Local Lemma, and (dually) Tur\'an's theorem follow from a small toolkit of positivity principles. \emph{Constructivity}: these existence proofs, despite their probabilistic framing, are finite and constructive at heart.

\section{Preliminaries and Notation}

For $n \in \N$ we write $[n] = \{0, \dots, n-1\}$ and $K_n$ for the complete graph on $[n]$, with $\binom{n}{2}$ edges. An \emph{edge two-coloring} of $K_n$ assigns to each unordered pair of distinct vertices a color in $\{\text{red}, \text{blue}\}$. For $S \subseteq [n]$, its \emph{internal edge set} $E(S)$ consists of the unordered pairs of distinct vertices in $S$, so $|E(S)| = \binom{|S|}{2}$. A set $S$ is \emph{monochromatic} under $c$ if all edges of $E(S)$ share one color.

\begin{definition}[Arrow relation]
We say $n \to (k,k)$ if every edge two-coloring of $K_n$ contains a monochromatic $k$-clique. The diagonal Ramsey number is $R(k,k) = \min\{n : n \to (k,k)\}$. Thus $R(k,k) > n$ is precisely $\neg\,(n \to (k,k))$: some coloring of $K_n$ has no monochromatic $k$-clique.
\end{definition}

For the measure-theoretic sections we fix a probability space $(\Omega, \mathcal{F}, \mu)$ with $\mu(\Omega)=1$ and a finite family of measurable ``bad events'' $A_i \subseteq \Omega$, $i \in \iota$. The object of interest is the ``all good'' event $\bigcap_i A_i^c$.

\section{Erd\H{o}s's Ramsey Lower Bound by Finite Counting}

Let $N = \binom{n}{2}$, so there are exactly $2^N$ edge two-colorings.

\begin{lemma}[Internal edge count]
For any vertex set $S$, $|E(S)| = \binom{|S|}{2}$.
\end{lemma}
\begin{proof}
Internal edges of $S$ are exactly the two-element subsets of $S$.
\end{proof}

\begin{lemma}[Union-bound count]\label{lem:count}
Fix a $k$-element vertex set $S$. The number of colorings under which $S$ is monochromatic is at most $2 \cdot 2^{\,N - \binom{k}{2}}$.
\end{lemma}
\begin{proof}
Such a coloring is determined by the single common color on the $\binom{k}{2}$ internal edges of $S$ (2 choices) and an arbitrary assignment on the remaining $N - \binom{k}{2}$ edges. Restricting to the outside edges is injective once the common color is fixed; summing the two color cases and bounding each restriction count by $2^{N-\binom{k}{2}}$ gives the claim.
\end{proof}

\begin{theorem}[Erd\H{o}s's counting theorem]\label{thm:count}
Let $2 \le k \le n$. If $2\binom{n}{k} < 2^{\binom{k}{2}}$, then $\neg\,(n \to (k,k))$; equivalently $R(k,k) > n$.
\end{theorem}
\begin{proof}
Suppose $n \to (k,k)$. Then every one of the $2^N$ colorings makes some $k$-set $S$ monochromatic, so
\[
2^N \le \sum_{|S|=k} |M_S| \le \binom{n}{k}\cdot 2 \cdot 2^{N-\binom{k}{2}},
\]
by Lemma~\ref{lem:count} and there being $\binom{n}{k}$ sets $S$. Dividing by $2^{N-\binom{k}{2}}$ gives $2^{\binom{k}{2}} \le 2\binom{n}{k}$, contradicting the hypothesis.
\end{proof}

The quantity $2\binom{n}{k}2^{-\binom{k}{2}}$ is exactly the expected number of monochromatic $k$-cliques under a uniform random coloring; Theorem~\ref{thm:count} says that when this expectation is below one, a clique-free coloring exists. The argument is a finite inequality between cardinalities.

\begin{lemma}[Exponent inequality]\label{lem:exp}
For all $k$, $\lfloor k/2\rfloor \cdot k \le \binom{k}{2} + \lfloor k/2\rfloor$.
\end{lemma}

\begin{lemma}[Factorial lower bound]\label{lem:fact}
For $k \ge 3$, $2^{\lfloor k/2\rfloor + 1} < k!$.
\end{lemma}

\begin{theorem}[Number-theoretic core]\label{thm:core}
For $k \ge 3$ and $n = 2^{\lfloor k/2\rfloor}$, $\;2\binom{n}{k} < 2^{\binom{k}{2}}$.
\end{theorem}
\begin{proof}
From $n^{\underline{k}} = k!\binom{n}{k}$ and $n^{\underline{k}} \le n^k$ we get $k!\cdot 2\binom{n}{k} \le 2n^k$. With $n = 2^{\lfloor k/2\rfloor}$, Lemma~\ref{lem:exp} gives $2n^k = 2^{1 + \lfloor k/2\rfloor k} \le 2^{\binom{k}{2} + \lfloor k/2\rfloor + 1}$, and Lemma~\ref{lem:fact} gives $2^{\lfloor k/2\rfloor + 1} < k!$, whence $2^{\binom{k}{2}+\lfloor k/2\rfloor + 1} < k!\,2^{\binom{k}{2}}$. Chaining and cancelling $k! > 0$ yields the claim.
\end{proof}

\begin{corollary}[Erd\H{o}s's lower bound]
For $k \ge 3$, $R(k,k) > 2^{k/2}$.
\end{corollary}
\begin{proof}
Combine Theorem~\ref{thm:core} with Theorem~\ref{thm:count} at $n = 2^{\lfloor k/2\rfloor}$ (handling the trivial regime $k > 2^{\lfloor k/2\rfloor}$ separately).
\end{proof}

\noindent\textbf{Concrete instances.} $R(4,4) > 5$: since $2\binom54 = 10 < 2^6 = 64$, some coloring of $K_5$ has no monochromatic $K_4$, so $R(4,4)\ge 6$. Likewise $R(6,6) > 8$, since $2\binom86 = 56 < 2^{15} = 32768$.

\section{The Probabilistic Method in a General Probability Space}

\begin{theorem}[First-moment positivity]
If $\sum_i \mu(A_i) < 1$, then $\mu\!\left(\bigcap_i A_i^c\right) > 0$.
\end{theorem}
\begin{proof}
By subadditivity $\mu(\bigcup_i A_i) \le \sum_i \mu(A_i) < 1$; since $\bigcap_i A_i^c = (\bigcup_i A_i)^c$, $\mu(\bigcap_i A_i^c) = 1 - \mu(\bigcup_i A_i) > 0$.
\end{proof}

\begin{corollary}[Probabilistic method]
If $\sum_i \mu(A_i) < 1$, some outcome $\omega$ satisfies $\omega \notin A_i$ for all $i$.
\end{corollary}

\begin{theorem}[Independent LLL, product formula]
If $\{A_i\}$ are mutually independent, then $\mu\!\left(\bigcap_i A_i^c\right) = \prod_i (1 - \mu(A_i))$.
\end{theorem}
\begin{proof}
Independence is inherited by the complements $A_i^c$; the multiplication rule gives $\mu(\bigcap_i A_i^c) = \prod_i \mu(A_i^c)$, and $\mu(A_i^c) = 1 - \mu(A_i)$.
\end{proof}

\begin{corollary}[Independent LLL, positivity]
If $\{A_i\}$ are mutually independent with $\mu(A_i) < 1$ for all $i$, then $\mu(\bigcap_i A_i^c) > 0$, so some outcome avoids all $A_i$.
\end{corollary}

\begin{definition}[Conditional avoidability]
The family $\{A_i\}$ is \emph{conditionally avoidable} if for every finite $S \subseteq \iota$ and every $i \notin S$,
\[
\mu\!\Big(\bigcap_{j\in S}A_j^c\Big) > 0 \;\Longrightarrow\; \mu\!\Big(A_i \cap \bigcap_{j\in S}A_j^c\Big) < \mu\!\Big(\bigcap_{j\in S}A_j^c\Big),
\]
equivalently $\mu(A_i \mid \bigcap_{j\in S}A_j^c) < 1$.
\end{definition}

\begin{theorem}[Chain-rule positivity, induction form]\label{thm:chain}
If $\{A_i\}$ is conditionally avoidable, then $\mu\!\left(\bigcap_{j\in S}A_j^c\right) > 0$ for every finite $S \subseteq \iota$.
\end{theorem}
\begin{proof}
Induction on $S$. For $S = \emptyset$ the intersection is $\Omega$, of measure $1$. For the step, with $i \notin S$ and $\mu(\bigcap_{j\in S}A_j^c) > 0$,
\[
\bigcap_{j\in S\cup\{i\}}A_j^c = \Big(\bigcap_{j\in S}A_j^c\Big)\setminus\Big(A_i\cap\bigcap_{j\in S}A_j^c\Big),
\]
whose measure is $\mu(\bigcap_{j\in S}A_j^c) - \mu(A_i\cap\bigcap_{j\in S}A_j^c) > 0$ by conditional avoidability.
\end{proof}

\begin{theorem}[Chain-rule LLL]
If $\{A_i\}_{i\in\iota}$ (finite $\iota$) is conditionally avoidable, then $\mu(\bigcap_i A_i^c) > 0$, and some outcome $\omega$ satisfies $\omega \notin A_i$ for all $i$.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:chain} with $S = \iota$; positivity gives nonemptiness.
\end{proof}

Specializing to independent events, $\mu(A_i \mid \bigcap_{j\in S}A_j^c) = \mu(A_i) < 1$, recovering the independent case. For the asymmetric Local Lemma with degree $d$ and $e\,p\,(d+1)\le 1$, the remaining work is to verify conditional avoidability via the induction $\mu(A_i \mid \bigcap_{j\in S}A_j^c) \le 2p$.

\section{Tur\'an's Theorem: the Extremal Dual}

\begin{definition}
A graph $G$ is $K_{r+1}$-\emph{free} if it contains no $r+1$ pairwise-adjacent vertices. The \emph{Tur\'an graph} $T(n,r)$ is the complete $r$-partite graph on $n$ vertices with parts as equal as possible; it is $K_{r+1}$-free.
\end{definition}

\begin{theorem}[Tur\'an, combinatorial form]\label{thm:turan1}
If $G$ is $K_{r+1}$-free on $n$ vertices with $r \ge 1$, then $2r\,|E(G)| \le (r-1)n^2$.
\end{theorem}
\begin{proof}
Among $K_{r+1}$-free graphs on $n$ vertices, an edge-maximal one is isomorphic to $T(n,r)$; hence $|E(G)| \le |E(T(n,r))|$, and a direct count gives $2r\,|E(T(n,r))| \le (r-1)n^2$.
\end{proof}

\begin{theorem}[Tur\'an, real-analytic form]
Under the hypotheses of Theorem~\ref{thm:turan1}, $|E(G)| \le \left(1 - \frac1r\right)\frac{n^2}{2}$.
\end{theorem}
\begin{proof}
Divide Theorem~\ref{thm:turan1} by $2r > 0$ and simplify $\frac{(r-1)n^2}{2r} = (1 - \frac1r)\frac{n^2}{2}$.
\end{proof}

The bound is tight, attained by $T(n,r)$ when $r \mid n$, and existence of the extremal object is fully constructive.

\section{Algorithms and Constructivity}

Theorem~\ref{thm:count} makes no reference to probability: it is an inequality between cardinalities, so a clique-free coloring can in principle be certified by finite search, which the theorem guarantees is nonempty. Tur\'an's extremal graph is written down explicitly. And the Local Lemma admits the Moser--Tardos resampling algorithm: sample all variables; while some bad event holds, resample the variables it depends on; output when none holds. Under $e\,p\,(d+1)\le 1$ this terminates in an expected number of resamplings bounded roughly linearly in the number of events, by an entropy-compression / witness-tree argument. Erd\H{o}s's ``non-constructive'' proofs are algorithms in disguise.

\section{Discussion and Future Directions}

\begin{enumerate}[leftmargin=*]
\item \textbf{General (asymmetric) Lov\'asz Local Lemma.} Verify conditional avoidability from a dependency graph of maximum degree $d$ with $e\,p\,(d+1)\le 1$, via the induction $\mu(A_i \mid \bigcap_{j\in S}A_j^c) \le 2p$.
\item \textbf{Moser--Tardos constructive LLL.} Formalize the resampling algorithm and its expected $O(n\cdot d)$ running-time bound.
\item \textbf{Ramsey numbers as a defined quantity.} Combine the arrow relation and counting bounds to define $R(k,k)$ and derive both $R(k,k) > 2^{k/2}$ and small-case computations.
\item \textbf{Higher moments.} Extend to second-moment and Janson-type inequalities.
\item \textbf{Off-diagonal and hypergraph Ramsey bounds.} Generalize the counting theorem to $R(s,t)$ and $r$-uniform hypergraphs.
\end{enumerate}

\section{Conclusion}

We presented a unified, self-contained account of three pillars of the probabilistic method: Erd\H{o}s's exponential Ramsey lower bound proved by finite counting; a measure-theoretic toolkit comprising the first-moment principle, the independent Lov\'asz Local Lemma, and a chain-rule positivity principle; and Tur\'an's theorem with its explicit extremal graph. Throughout, the emphasis has been on constructivity: these celebrated existence results are, at bottom, finite counting statements and explicit constructions.

\end{document}

