import math

def erdos_counting_holds(n: int, k: int) -> bool:
    """True iff 2*C(n,k) < 2^{C(k,2)}: then K_n has a K_k-free colouring, R(k,k) > n."""
    return 2 * math.comb(n, k) < 2 ** math.comb(k, 2)

def expected_mono_cliques(n: int, k: int) -> float:
    """Expected number of monochromatic K_k under a uniform random colouring of K_n."""
    return 2.0 * math.comb(n, k) * 2.0 ** (-math.comb(k, 2))

for k in range(3, 12):
    n = 2 ** (k // 2)
    print(k, n, round(expected_mono_cliques(n, k), 6), erdos_counting_holds(n, k))

for n, k in [(5, 4), (8, 6)]:
    print(f"R({k},{k}) > {n}:", 2 * math.comb(n, k), "<", 2 ** math.comb(k, 2))

import random
from typing import Dict, List, Tuple

Clause = List[Tuple[int, bool]]

def satisfied(clause: Clause, a: Dict[int, bool]) -> bool:
    return any(a[v] == pol for v, pol in clause)

def moser_tardos(num_vars: int, clauses: List[Clause], rng: random.Random) -> Tuple[Dict[int, bool], int]:
    a = {v: rng.random() < 0.5 for v in range(num_vars)}
    steps = 0
    while True:
        bad = [c for c in clauses if not satisfied(c, a)]
        if not bad:
            return a, steps
        for v, _ in rng.choice(bad):
            a[v] = rng.random() < 0.5
        steps += 1

rng = random.Random(2026)
clauses = [[(v, rng.random() < 0.5) for v in rng.sample(range(40), 5)] for _ in range(60)]
a, steps = moser_tardos(40, clauses, rng)
print("satisfied:", all(satisfied(c, a) for c in clauses), "resamplings:", steps)

from itertools import combinations
from typing import List

def turan_graph_edges(n: int, r: int) -> int:
    sizes = [n // r + (1 if i < n % r else 0) for i in range(r)]
    return n * (n - 1) // 2 - sum(s * (s - 1) // 2 for s in sizes)

def turan_bound(n: int, r: int) -> float:
    return (1.0 - 1.0 / r) * n * n / 2.0

for n, r in [(6, 2), (9, 3), (10, 3), (12, 4), (15, 5)]:
    e, b = turan_graph_edges(n, r), turan_bound(n, r)
    print(n, r, e, round(b, 2), e <= b + 1e-9)

