from itertools import combinations
from typing import List, Set, Tuple

def turan_graph(n: int, r: int) -> Tuple[List[int], Set[Tuple[int, int]]]:
    """Return (part assignment, edge set) of the balanced complete r-partite graph."""
    part: List[int] = [v % r for v in range(n)]
    edges: Set[Tuple[int, int]] = {
        (u, v) for u, v in combinations(range(n), 2) if part[u] != part[v]
    }
    return part, edges

def turan_edge_count(n: int, r: int) -> int:
    sizes: List[int] = [n // r + (1 if i < n % r else 0) for i in range(r)]
    return n * (n - 1) // 2 - sum(s * (s - 1) // 2 for s in sizes)

part, edges = turan_graph(9, 3)
print("edges:", len(edges), "closed form:", turan_edge_count(9, 3))
